BEGIN;
DO $test$
DECLARE owner_id uuid;a uuid;b uuid;c uuid;r uuid;secret uuid;session_a uuid;session_b uuid;j jsonb;poll uuid;ledger_before bigint;ledger_after bigint;
BEGIN
 SELECT user_id INTO owner_id FROM public.admins LIMIT 1;SELECT id INTO a FROM public.profiles p WHERE NOT coalesce(banned,false)AND NOT EXISTS(SELECT 1 FROM public.admins WHERE user_id=p.id)ORDER BY id LIMIT 1;
 SELECT id INTO b FROM public.profiles p WHERE id<>a AND NOT coalesce(banned,false)AND NOT EXISTS(SELECT 1 FROM public.admins WHERE user_id=p.id)ORDER BY id LIMIT 1;
 SELECT id INTO c FROM public.profiles p WHERE id NOT IN(a,b)AND NOT coalesce(banned,false)AND NOT EXISTS(SELECT 1 FROM public.admins WHERE user_id=p.id)ORDER BY id LIMIT 1;
 ASSERT owner_id IS NOT NULL AND a IS NOT NULL AND b IS NOT NULL AND c IS NOT NULL,'Fixtures';
 SELECT count(*)INTO ledger_before FROM public.points_ledger;
 PERFORM set_config('request.jwt.claim.sub','',true);BEGIN PERFORM public.xr_voice_lobby_presence();RAISE EXCEPTION 'Anon allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 ASSERT public.xr_voice_join()->>'error'='not_open','Staged';ASSERT public.xr_voice_lobby_presence()->'participants'='[]'::jsonb,'Honest empty';ASSERT public.xr_voice_history()->'last_room'='null'::jsonb,'No fake last room';
 BEGIN PERFORM public.xr_voice_settings_admin('{"enabled":true}');RAISE EXCEPTION 'Player config bypass';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 ASSERT(public.xr_voice_settings_admin('{"enabled":true,"default_seat_cap":2,"min_attendance_seconds":60,"streak_days":2,"streak_reward_coins":20,"first_speaker_limit":1}')->>'ok')::boolean,'Admin config';
 j:=public.xr_voice_room_admin(jsonb_build_object('title','Rollback room','topic','Real test topic','next_topic','Next real test','status','live','starts_at',now()-interval '1 minute'));ASSERT(j->>'ok')::boolean,j::text;r:=(j->>'room_id')::uuid;
 j:=public.xr_voice_room_admin(jsonb_build_object('title','Rank room','status','scheduled','starts_at',now()-interval '1 minute','ends_at',now()+interval '8 minutes','is_secret',true,'required_rank','Heroic'));ASSERT(j->>'ok')::boolean,j::text;secret:=(j->>'room_id')::uuid;
 ASSERT NOT(public.xr_voice_room_admin('{"status":"live"}',secret)->>'ok')::boolean,'Secret audio cannot open';
 UPDATE public.profiles SET show_activity=true WHERE id IN(a,b,c);INSERT INTO public.xr_sf_player_prefs(user_id,discoverable)VALUES(a,true),(b,true),(c,true)ON CONFLICT(user_id)DO UPDATE SET discoverable=true;
 DELETE FROM public.blocks WHERE user_id IN(a,b,c)AND blocked_id IN(a,b,c);
 PERFORM set_config('request.jwt.claim.sub',a::text,true);j:=public.xr_voice_join(r);ASSERT j->>'state'='joined',j::text;session_a:=(j->>'session_id')::uuid;
 ASSERT(public.xr_voice_join(r)->>'already_joined')::boolean,'Idempotent join';ASSERT public.xr_voice_heartbeat(r,gen_random_uuid(),true)->>'error'='session_expired','Wrong session rejected';
 ASSERT(public.xr_voice_heartbeat(r,session_a,false)->>'ok')::boolean,'Own heartbeat';
 ASSERT(public.xr_voice_hand_raise(true,r)->>'hand_raised')::boolean,'Hand raise';
 j:=public.xr_voice_lobby_presence(r);ASSERT(j->>'joined_count')::integer=1,'One genuine session';ASSERT NOT(j->'participants'->0->>'speaking')::boolean,'Mute is not speech';
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j->'participants')x,jsonb_object_keys(x)k WHERE k NOT IN('id','username','ign','avatar_url','speaking','hand_raised','is_friend','is_squadmate')),'Private payload allowlist';
 ASSERT NOT(public.xr_voice_poll_create(r,'Where?','["A","B"]')->>'ok')::boolean,'Unconfirmed speaker cannot create';
 PERFORM set_config('request.jwt.claim.sub',b::text,true);j:=public.xr_voice_join(r);ASSERT j->>'state'='joined','Second seat';session_b:=(j->>'session_id')::uuid;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);j:=public.xr_voice_join(r);ASSERT j->>'state'='waitlisted'AND(j->>'rank')::integer=1,'Real waitlist';
 ASSERT public.xr_voice_hand_raise(true,r)->>'error'='join_first','Waiter cannot raise';
 PERFORM set_config('request.jwt.claim.sub',b::text,true);PERFORM public.xr_voice_leave(r,session_b);
 PERFORM set_config('request.jwt.claim.sub',c::text,true);ASSERT public.xr_voice_join(r)->>'state'='joined','Waiter claims freed seat';
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 j:=public.xr_voice_speaker_confirm(r,a);ASSERT(j->>'badge_granted')::boolean,'First speaker actual admin confirmation';ASSERT(public.xr_voice_speaker_confirm(r,a)->>'already_confirmed')::boolean,'Speaker retry';
 ASSERT NOT(public.xr_voice_speaker_confirm(r,c)->>'badge_granted')::boolean,'Cap respected';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);j:=public.xr_voice_poll_create(r,'Which drop?','["A","B"]',60);ASSERT(j->>'ok')::boolean,j::text;poll:=(j->>'poll_id')::uuid;
 ASSERT(public.xr_voice_poll_vote(poll,0)->>'ok')::boolean,'One vote';ASSERT(public.xr_voice_poll_vote(poll,1)->>'already_voted')::boolean,'No duplicate changing votes';
 j:=public.xr_voice_poll_results(r);ASSERT(j->'poll'->>'votes')::integer=1 AND(j->'poll'->'counts'->>0)::integer=1,'Real poll totals';
 ASSERT public.xr_voice_heartbeat(r,session_a,true)->>'speaking_source'='client_vad_reported','Honest VAD provenance';
 UPDATE public.xr_voice_members SET speaking_reported_at=now()-interval '16 seconds'WHERE room_id=r AND user_id=a;
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.xr_voice_lobby_presence(r)->'participants')x WHERE x->>'id'=a::text AND(x->>'speaking')::boolean),'Stale speech clears';
 UPDATE public.profiles SET show_activity=false WHERE id=a;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.xr_voice_lobby_presence(r)->'participants')x WHERE x->>'id'=a::text),'Opt-out private';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);ASSERT NOT(public.xr_voice_room_eligibility(secret)->>'rank_eligible')::boolean,'Editable rank not enough';
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);PERFORM public.xr_voice_rank_admin(a,'Heroic');PERFORM set_config('request.jwt.claim.sub',a::text,true);j:=public.xr_voice_room_eligibility(secret);ASSERT(j->>'rank_eligible')::boolean AND NOT(j->>'audio_admission_available')::boolean,'Eligibility distinct from audio';ASSERT public.xr_voice_join(secret)->>'error'='private_signaling_required','No fake secure room';
 -- Bounded server time only: a gap cannot manufacture hours of credit.
 UPDATE public.xr_voice_members SET heartbeat_at=clock_timestamp()-interval '1 hour',expires_at=clock_timestamp()+interval '1 minute',attended_seconds=0 WHERE room_id=r AND user_id=a;
 ASSERT(public.xr_voice_heartbeat(r,session_a,false)->>'ok')::boolean,'Gap heartbeat';ASSERT(SELECT attended_seconds FROM public.xr_voice_members WHERE room_id=r AND user_id=a)<=45,'Gap capped45sec';
 UPDATE public.xr_voice_members SET expires_at=clock_timestamp()-interval '1 second'WHERE room_id=r AND user_id=c;
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.xr_voice_lobby_presence(r)->'participants')x WHERE x->>'id'=c::text),'Expired members hidden';
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 ASSERT NOT(public.xr_voice_attendance_confirm(r,a)->>'ok')::boolean,'Insufficient attendance';
 UPDATE public.xr_voice_members SET attended_seconds=60,joined_at=now()WHERE room_id=r AND user_id=a;
 ASSERT(public.xr_voice_attendance_confirm(r,a)->>'ok')::boolean,'Bounded attendance observed';ASSERT(SELECT count(*)FROM public.points_ledger)=ledger_before,'Rewards default disabled';
 INSERT INTO public.xr_voice_attendance_days(user_id,day,room_id,confirmed_by)VALUES(a,(now()AT TIME ZONE 'Asia/Kolkata')::date-1,r,owner_id);
 PERFORM public.xr_voice_settings_admin('{"rewards_enabled":true}');ASSERT(public.xr_voice_attendance_confirm(r,a)->>'reward_granted')::boolean,'Threshold awards ledger once';
 ASSERT NOT(public.xr_voice_attendance_confirm(r,a)->>'reward_granted')::boolean,'Retry no duplicate award';ASSERT(SELECT count(*)FROM public.points_ledger)=ledger_before+1,'Exactly one ledger award';
 ASSERT(SELECT delta FROM public.points_ledger WHERE kind='voice_streak'AND user_id=a ORDER BY id DESC LIMIT 1)=20,'Configured amount';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);ASSERT(public.xr_voice_streak_status()->>'streak_days')::integer=2,'Consecutive days';
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);ASSERT(public.xr_voice_room_admin('{"status":"ended"}',r)->>'ok')::boolean,'Room end';
 j:=public.xr_voice_history();ASSERT(j->'last_room'->>'peak_count')::integer=2 AND j->'last_room'->>'ended_at'IS NOT NULL,'Actual peak history';
 ASSERT public.xr_voice_heartbeat(r,session_a)->>'error'='room_closed','End stops heartbeat';
END $test$;
SET LOCAL ROLE anon;
DO $grants$BEGIN ASSERT NOT has_function_privilege(current_user,'public.xr_voice_lobby_presence(uuid)','EXECUTE'),'Anon denied';END $grants$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $grants$BEGIN ASSERT NOT has_table_privilege(current_user,'public.xr_voice_members','SELECT,INSERT,UPDATE,DELETE'),'Members private';ASSERT NOT has_table_privilege(current_user,'public.xr_voice_settings','SELECT,INSERT,UPDATE,DELETE'),'Settings private';ASSERT has_function_privilege(current_user,'public.xr_voice_lobby_presence(uuid)','EXECUTE'),'JWT contract';END $grants$;
RESET ROLE;

SELECT 'voice tests passed; fixtures reverted' result;
ROLLBACK;